import projects.parkinglot.parking.Ticket;
import projects.parkinglot.parking.VehicleTypeEnum;
import projects.parkinglot.payment.PaymentModeType;
import projects.parkinglot.pricing.PricingStrategyEnum;

public class Main {
    public static void main(String[] args) {
        ParkingLot lot = new ParkingLot(1, PricingStrategyEnum.TIME_BASED);
        ParkingFloor floor1 = new ParkingFloor(1);
        floor1.addParkingSpot(new ParkingSpot(1, VehicleTypeEnum.CAR));
        floor1.addParkingSpot(new ParkingSpot(2, VehicleTypeEnum.AUTO));
        floor1.addParkingSpot(new ParkingSpot(3, VehicleTypeEnum.BIKE));
        floor1.addParkingSpot(new ParkingSpot(4, VehicleTypeEnum.TRUCK));


        ParkingFloor floor2 = new ParkingFloor(2);
        floor2.addParkingSpot(new ParkingSpot(5, VehicleTypeEnum.CAR));
        floor2.addParkingSpot(new ParkingSpot(6, VehicleTypeEnum.AUTO));
        floor2.addParkingSpot(new ParkingSpot(7, VehicleTypeEnum.BIKE));
        floor2.addParkingSpot(new ParkingSpot(8, VehicleTypeEnum.TRUCK));

        lot.addParkingFloor(floor1);
        lot.addParkingFloor(floor2);

        Ticket ticket1 = lot.parkVehicle(VehicleTypeEnum.AUTO);
        if(ticket1 != null) {
            System.err.println("Parked Auto at " + ticket1.toString());
        } else {
            System.err.println("Found no place to place Auto 1");
        }
        Ticket ticket2 = lot.parkVehicle(VehicleTypeEnum.AUTO);
        if(ticket2 != null) {
            System.err.println("Parked Auto at " + ticket2.toString());
        } else {
            System.err.println("Found no place to place Auto 2");
        }
        Ticket ticket3 = lot.parkVehicle(VehicleTypeEnum.AUTO);
        if(ticket3 != null) {
            System.err.println("Parked Auto at " + ticket3.toString());
        } else {
            System.err.println("Found no place to place Auto 3");
        }

        lot.unparkVehicle(ticket1, PaymentModeType.CASH);
        ticket3 = lot.parkVehicle(VehicleTypeEnum.AUTO);
        if(ticket3 != null) {
            System.err.println("Parked Auto at " + ticket3.toString());
        } else {
            System.err.println("Found no place to place Auto 3");
        }
    }
}

package projects.parkinglot.parking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * ParkingFloor
 */
public class ParkingFloor {
    private final int id;
    private final Map<VehicleTypeEnum, List<ParkingSpot>> availableSpots;

    public ParkingFloor(int id){
        this.id = id;
        this.availableSpots = new HashMap<>();
    }

    public int getId() {
        return this.id;
    }

    public void addParkingSpot(ParkingSpot spot){
        VehicleTypeEnum newSpotType = spot.getType();
        this.availableSpots.putIfAbsent(newSpotType, new ArrayList<>());
        this.availableSpots.get(newSpotType).add(spot);
    }

    public synchronized boolean hasEmptySpot(VehicleTypeEnum type) {
        return this.availableSpots.containsKey(type) && !this.availableSpots.get(type).isEmpty();
    }

    public synchronized ParkingSpot parkVehicle(VehicleTypeEnum type){
        if(!this.hasEmptySpot(type)){
            return null;
        }
        ParkingSpot spot = this.availableSpots.get(type).removeFirst();
        return spot;
    }

    public synchronized void unparkVehicle(Ticket ticket){
        ParkingSpot spot = ticket.getSpot();
        this.availableSpots.get(ticket.getType()).add(spot);
    }
}

package projects.parkinglot.parking;

import java.util.ArrayList;
import java.util.List;
import projects.parkinglot.payment.PaymentModeType;
import projects.parkinglot.payment.PaymentProcessor;
import projects.parkinglot.pricing.PricingProcessor;
import projects.parkinglot.pricing.PricingStrategyEnum;

public class ParkingLot {
    private final int id;
    private final List<ParkingFloor> floors;
    private final PricingStrategyEnum strategy;
    private final PricingProcessor pricingProcessor;
    private final PaymentProcessor paymentProcessor;

    public ParkingLot(int id, PricingStrategyEnum strategy) {
        this.id = id;
        this.strategy = strategy;
        this.floors = new ArrayList<>();
        this.paymentProcessor = PaymentProcessor.getPaymentInstance();
        this.pricingProcessor = PricingProcessor.getPricingInstance();
    }

    public int getId() {
        return this.id;
    }

    public void addParkingFloor(ParkingFloor floor){
        this.floors.add(floor);
    }

    public synchronized Ticket parkVehicle(VehicleTypeEnum vehicleType){
        for (ParkingFloor floor : this.floors) {
            if(floor.hasEmptySpot(vehicleType)) {
                ParkingSpot spot = floor.parkVehicle(vehicleType);
                if(spot == null) {
                    continue;
                }
                return new Ticket(vehicleType, spot, floor);
            }
        }
        return null;
    }

    public synchronized void unparkVehicle(Ticket ticket, PaymentModeType mode){
        double amountToPay = this.pricingProcessor.calculateAmount(this.strategy, ticket);
        if(!ticket.isPaid()) {
            paymentProcessor.pay(mode, amountToPay);
            ticket.markPaid();
        }
        ticket.getFloor().unparkVehicle(ticket);
    }
}

